'use strict';
let C, products=[], currentPage; const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(name,alt,cls='')=>`<img class="${cls}" src="assets/${C?.assets?.[name]||name}" alt="${esc(alt)}" loading="lazy" decoding="async">`;
const icon=(name)=>{const files={weave:'fabric',measure:'measure',wash:'laundry',thread:'yarn',leaf:'cotton',heart:'cushion'};if(files[name])return `<img class="themed-icon" src="assets/icon-${files[name]}.png" alt="" loading="lazy">`;const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',menu:'<path d="M3 8h18M3 16h18"/>',leaf:'<path d="M20 3C7 2 2 10 6 17c8 5 16-2 14-14ZM5 21 16 8"/>',weave:'<path d="M4 3v18M10 3v18M16 3v18M22 3v18M2 5h20M2 11h20M2 17h20"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',measure:'<path d="M3 7h18v10H3ZM7 7v5m5-5v3m5-3v5"/>',wash:'<path d="m3 7 2 13h14l2-13M4 10q3-4 6 0t6 0 4 0"/>',thread:'<path d="M6 3h12M6 21h12M8 3v18m8-18v18M8 6h8M8 10h8M8 14h8M8 18h8"/>',heart:'<path d="M12 21 3 12C-3 3 9 0 12 7 15 0 27 3 21 12Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.weave}</svg>`;};
const link=(slug)=>`${slug}.html`;
const sectionHead=(title,copy='',right='')=>`<div class="section-head" data-aos><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}${right}</div>`;
const button=(label,href,cls='')=>`<a class="btn ${cls}" href="${href}">${label}</a>`;
function buildProducts(){products=C.products||[];}
function layout(){ $('#header').innerHTML=`<div class="header-inner container"><a class="brand" href="index.html">${img(C.logo.replace('assets/',''),'','brand-mark')}<span>${esc(C.siteName)}</span></a><nav class="desktop-nav" aria-label="Main navigation"><a href="index.html" ${currentPage==='index'?'aria-current="page"':''}>Home</a><div class="nav-drop"><button aria-expanded="false">Collections <span class="small-plus">+</span></button><div class="dropdown">${C.collections.map(c=>`<a href="${link(c.slug)}">${c.name}</a>`).join('')}</div></div><a href="index.html#about">About Us</a><a href="materials-care.html">Materials & Care</a><a href="index.html#contact">Contact</a></nav><div class="header-actions"><button class="icon-btn open-search" aria-label="Search website">${icon('search')}</button><button class="icon-btn menu-toggle" aria-label="Open menu" aria-expanded="false">${icon('menu')}</button></div></div><nav class="mobile-nav" aria-label="Mobile navigation" hidden><a href="index.html">Home</a>${C.collections.map(c=>`<a href="${link(c.slug)}">${c.name}</a>`).join('')}<a href="index.html#about">About Us</a><a href="materials-care.html">Materials & Care</a><a href="index.html#contact">Contact Us</a><a class="mobile-email" href="mailto:${esc(C.email)}">${esc(C.email)}</a></nav>`;
$('#footer').innerHTML=`<div class="container footer-top"><div class="footer-brand"><a class="brand" href="index.html">${img(C.logo.replace('assets/',''),'','brand-mark')}<span>${esc(C.siteName)}</span></a><h2>${esc(C.footerText)}</h2><a class="email-link" href="mailto:${esc(C.email)}">${esc(C.email)}</a>${C.address?`<p>${esc(C.address)}</p>`:''}</div><div><h3>Explore</h3>${C.collections.map(c=>`<a href="${link(c.slug)}">${c.name}</a>`).join('')}</div><div><h3>Good to know</h3><a href="index.html#about">About Us</a><a href="index.html#contact">Contact Us</a><a href="materials-care.html">Materials & Care</a><a href="shipping-returns.html">Shipping & Returns</a><a href="privacy-policy.html">Privacy Policy</a><a href="terms-conditions.html">Terms & Conditions</a><a href="cookies.html">Cookie Policy</a>${Object.entries(C.links).filter(([,v])=>v).map(([k,v])=>`<a href="${esc(v)}" rel="noopener">${esc(k)}</a>`).join('')}</div></div><div class="container footer-bottom"><p>${esc(C.disclaimer)}</p><span>© ${new Date().getFullYear()} ${esc(C.copyright)}</span><a href="#main">Back to top ↑</a></div><div class="container icon-attribution">Icons: <a href="https://www.flaticon.com/authors/magnific">Magnific</a>, <a href="https://www.flaticon.com/authors/smashicons">Smashicons</a>, <a href="https://www.flaticon.com/authors/hexagon075">Hexagon075</a> & <a href="https://www.flaticon.com/authors/kiranshastry">Kiranshastry</a> / <a href="https://www.flaticon.com/">Flaticon</a>.</div>`;}
function productCard(p){return `<article class="product-card" data-product-id="${p.id}"><button class="product-image" data-product="${p.id}" aria-label="View ${p.name}">${img(p.image,p.name)}<span class="quick-view">Explore details</span></button><div class="product-info"><div><h3><button data-product="${p.id}">${p.name}</button></h3><p>${p.material} · ${p.size}</p></div><span class="swatch ${p.colour.toLowerCase()}" title="${p.colour}"></span></div></article>`;}
function carousel(items){return `<div class="carousel" data-carousel><div class="carousel-track">${items.join('')}</div><div class="carousel-controls"><span class="carousel-note">A little texture goes a long way.</span><div><button data-prev aria-label="Previous items">←</button><button data-next aria-label="Next items">→</button></div></div></div>`;}
function form(){return `<form class="contact-form"><div class="form-grid"><label>Your name <input name="name" autocomplete="name" required maxlength="100" placeholder="Name"></label><label>Email address <input name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@example.com"></label></div><label>What brings you here?<select name="subject">${C.form.subjects.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>Your message<textarea name="message" required minlength="10" maxlength="${C.form.maxLength}" rows="4" placeholder="Tell us about your space, the items you like, or your next idea…"></textarea></label><div class="honey" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input type="checkbox" name="consent" required><span>I have read the <a href="privacy-policy.html">Privacy Policy</a> and agree to the processing of my enquiry.</span></label><button class="btn dark" type="submit">Send your request ${icon('arrow')}</button><p class="form-status" role="status" aria-live="polite"></p></form>`;}
function contact(){return `<section id="contact" class="section contact-section container"><div class="contact-intro" data-aos><span class="tiny">LET’S MAKE SOMETHING LOVELY</span><h2>${esc(C.collaboration.title)}</h2><p>${esc(C.collaboration.text)}</p><a class="email-link" href="mailto:${esc(C.email)}">${esc(C.email)}</a></div><div class="contact-card" data-aos>${form()}</div></section>`;}
function home(){return `<section class="hero container" aria-labelledby="hero-title"><div class="hero-topline"><span>TEXTURE. COLOUR. EVERYDAY COMFORT.</span><span>THE ART OF FEELING AT HOME</span></div><h1 id="hero-title"><span>HOME</span><span>TEXTILES</span></h1><div class="hero-orbit" aria-hidden="true"></div><img src="assets/bag.webp" class="hero-bag" alt="Sculptural woven natural-fibre tote bag with warm brown handles" fetchpriority="high"><div class="hero-copy"><p>Little textures. <br>Beautiful everyday living.</p>${button('Explore the collection','#collections','dark')}</div><div class="hero-side"><span>A softer perspective</span><p>Considered pieces.<br>Comfort, woven in.</p></div><a href="#about" class="hero-scroll">SCROLL TO FEEL AT HOME <span>↓</span></a></section>
<section id="about" class="section container about"><div class="about-photo" data-aos>${img('fabric.avif','Ochre, cream and rust fabric folds')}<span class="photo-caption">GOOD THINGS START WITH A THREAD.</span></div><div class="about-copy" data-aos><span class="tiny">ABOUT US</span><h2>Made for <br><em>your everyday.</em></h2><p>We bring colour, texture and comfort to the spaces you call home. From a cushion in your favourite chair to linen laid for a slow Sunday lunch, the smallest details can change how a room feels.</p><p>Explore tactile fabrics, thoughtful combinations and the practical details that make choosing easier.</p>${button('Find your texture','materials-care.html','outline')}<div class="values"><span>${icon('weave')}Beautiful textures</span><span>${icon('measure')}Clear sizing</span><span>${icon('wash')}Care made simple</span></div></div></section>
<section class="section container texture-section" id="collections">${sectionHead('A texture for every moment.','Start with a feeling. Find the pieces that bring it home.')}<div class="texture-panels" style="--panel-bg:url('assets/cushions.avif')">${C.collections.slice(0,4).map((c,i)=>`<a class="texture-panel" href="${link(c.slug)}" data-bg="assets/${c.image}" style="--own-bg:url('assets/${c.image}')"><div><h3>${c.name}</h3><p>${['The finishing touch.','A softer kind of slow.','Everyday, beautifully set.','A little line of colour.'][i]}</p><span class="panel-link">Explore collection</span></div></a>`).join('')}</div><div class="marquee" aria-label="Colour, texture, comfort"><div aria-hidden="true">${Array(4).fill('<span>Colour</span><i>✳</i><span>Texture</span><i>✳</i><span>Comfort</span><i>✳</i>').join('')}</div></div></section>
<section id="favourites" class="section container">${sectionHead('The everyday edit.','Warm tones. Lovely layers. Discover a few ideas to start with.',button('All collections','#collections','text-link'))}${carousel([products[2],products[7],products[9],products[13],products[3],products[6]].map(productCard))}</section>
<section id="materials" class="section material-section"><div class="container">${sectionHead('Feel the difference.','Every fabric has its own character. Compare the textures that suit your everyday.')}<div class="material-tabs" role="tablist" aria-label="Compare materials"><button role="tab" aria-selected="true" data-material="linen">Linen</button><button role="tab" aria-selected="false" data-material="cotton">Cotton</button><button role="tab" aria-selected="false" data-material="wool">Wool</button></div><div id="material-content" class="material-content"></div><a class="text-link" href="materials-care.html">Explore the fabric & care guide</a></div></section>
<section class="section container look-section" id="room-inspiration">${sectionHead('A room, beautifully layered.','Hover or tap the details. See how texture brings everything together.')}<div class="look-image" data-aos>${img('ref-17.avif','Warm interior styled with layered textiles')}<button class="hotspot" style="left:30%;top:43%" aria-label="Explore cushion styling" aria-expanded="false"><span>+</span><span class="hotspot-card"><strong>Soft contrast</strong>Pair a warm ochre cushion with an understated natural weave.<a href="cushion-covers.html">Cushion covers</a></span></button><button class="hotspot" style="left:78%;top:62%" aria-label="Explore throws" aria-expanded="false"><span>+</span><span class="hotspot-card"><strong>An easy layer</strong>A relaxed throw adds movement and a little everyday comfort.<a href="throws-blankets.html">Throws & blankets</a></span></button><button class="hotspot" style="left:93%;top:20%" aria-label="Explore room styling" aria-expanded="false"><span>+</span><span class="hotspot-card"><strong>Ground the palette</strong>Balance tactile fabrics with wood, ceramics and leafy greens.<a href="living-room.html">Living room</a></span></button></div></section>
<section class="section container before-section"><div class="before-copy" data-aos><span class="tiny">THE DIFFERENCE IS IN THE DETAILS</span><h2>Same room. <br><em>New feeling.</em></h2><p>A cushion here. A soft throw there. See how a few thoughtful layers turn a simple space into somewhere to settle in.</p><p class="subtle">Drag to reveal the styled room.</p>${button('Explore living room','living-room.html','outline')}</div><div class="comparison" data-aos>${img('living-before.avif','Living room before adding soft furnishings','before-image')}<div class="after-clip">${img('living.avif','The same living room styled with cushions and a throw','after-image')}</div><span class="compare-label before-label">Before</span><span class="compare-label after-label">After</span><div class="compare-divider"><span>↔</span></div><input aria-label="Compare room before and after styling" type="range" min="0" max="100" value="50"></div></section>
<section class="section container palette-section">${sectionHead('Find your colour story.','Start with one tone. Layer it with something unexpected.')}<div class="palette-tabs" role="tablist" aria-label="Colour stories"><button role="tab" aria-selected="true" data-palette="earth">Warm earth</button><button role="tab" aria-selected="false" data-palette="natural">Soft neutrals</button><button role="tab" aria-selected="false" data-palette="green">Grounded greens</button></div><div class="palette-content" id="palette-content"></div></section>
<section class="section container care-section"><div class="care-art" data-aos>${img('yarn.avif','Natural wool yarn with wooden knitting needles')}<svg class="thread-drawing" viewBox="0 0 400 100" aria-hidden="true"><path d="M0 50C70-40 80 140 160 50S260-20 280 50s90 45 120-10"/></svg></div><div data-aos><span class="tiny">A LITTLE CARE GOES A LONG WAY</span><h2>Love it. <br><em>Live with it.</em></h2><div class="accordions">${faq([['How do I choose the right size?','Measure your cushion insert, table or sofa before choosing. Each collection offers a sizing guide; ask us if you need help interpreting a measurement.'],['Can I mix different materials?','Absolutely. Start with a shared colour and vary the texture. A relaxed linen, a smooth cotton and a textured knit can sit beautifully together.'],['How should I care for my textiles?','Always follow the individual item’s sewn-in care label. Separate colours, avoid harsh treatments and check whether the item can be washed, dried or ironed.'],['How do I check availability?','Use the contact form with the collection, colour and size you are interested in. Availability and final item details are confirmed before any order is accepted.']])}</div></div></section>
${contact()}`;}
function faq(items){return items.map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('');}
const materialData={linen:{title:'Naturally relaxed.',image:'linen.avif',desc:'An airy texture with a beautifully lived-in character. Linen brings subtle variation and an easy drape to the home.',feel:'Crisp, textured, relaxed',best:'Cushion covers & table linens',care:'Check the label; wrinkles are part of its character.',note:'A lovely foundation for warm, natural spaces.'},cotton:{title:'Everyday softness.',image:'cotton.avif',desc:'Versatile and familiar, cotton offers a soft hand and a broad range of weaves. An easy starting point for everyday layering.',feel:'Soft, smooth, versatile',best:'Covers, throws & tablecloths',care:'Check colour and washing instructions on the item.',note:'Pair a fine cotton weave with a chunky knit.'},wool:{title:'A little more warmth.',image:'wool.avif',desc:'Rich texture for the moments you want to slow down. Wool brings natural depth and a warm, cocooning feel.',feel:'Warm, springy, textured',best:'Throws & blankets',care:'Use the wool-specific instructions on the label.',note:'A tactile finishing layer for your favourite chair.'}};
function renderMaterial(key){const m=materialData[key];$('#material-content').innerHTML=`${img(m.image,`${key} fabric texture`)}<div class="material-copy"><h3>${m.title}</h3><p>${m.desc}</p><dl><div><dt>The feel</dt><dd>${m.feel}</dd></div><div><dt>Lovely for</dt><dd>${m.best}</dd></div><div><dt>A care note</dt><dd>${m.care}</dd></div></dl><p class="serif-note">${m.note}</p></div>`;}
const palettes={earth:{title:'A warmer welcome.',image:'ref-18.avif',desc:'Ochre, rust and sun-warmed neutrals. Let a rich accent meet a quieter background for a room with a little more soul.',colours:['#b68a45','#9e583d','#d1bea1','#695245'],names:['Ochre','Terracotta','Oat','Cocoa']},natural:{title:'Room to exhale.',image:'ref-19.avif',desc:'Ivory, oat and soft stone. A gentle palette feels layered when you mix smooth surfaces with more expressive weaves.',colours:['#f1e9d8','#c9b99c','#a5a091','#736d61'],names:['Ivory','Oat','Stone','Taupe']},green:{title:'Bring the outside in.',image:'ref-20.avif',desc:'Olive and moss, grounded in warm neutrals. Add a leafy plant and simple wood details to complete the mood.',colours:['#75765a','#4d5947','#bfb69b','#b58159'],names:['Olive','Moss','Flax','Clay']}};
function renderPalette(k){const p=palettes[k];$('#palette-content').innerHTML=`${img(p.image,p.title)}<div><h3>${p.title}</h3><p>${p.desc}</p><div class="colour-chips">${p.colours.map((v,i)=>`<span><i style="background:${v}"></i>${p.names[i]}</span>`).join('')}</div>${button('Discover room collections','living-room.html','dark')}</div>`;}
function collection(c,index){const subset=products.filter(p=>p.collection===c.slug);const extras=['bedroom.avif','fabric.avif','linen.avif','cotton.avif','rug.avif','yarn.avif'];const heroPhotos=['ref-21.avif','ref-22.avif','ref-23.avif','ref-24.avif','living.avif','ref-25.avif'];return `<section class="collection-hero container hero-variant-${index%3}"><div class="collection-heading"><a class="back-link" href="index.html#collections">Home / Collections</a><h1>${c.name.replace(' & ',' &<br>')}</h1><p>${c.short}</p>${button('Explore the edit','#collection-products','dark')}</div><div class="collection-hero-photo">${img(c.heroImage||heroPhotos[index],c.name)}</div><span class="vertical-caption">TEXTURES TO LIVE WITH</span></section>
<section id="collection-products" class="section container">${sectionHead('Your next lovely layer.',c.intro)}<div class="filter-bar"><label>Colour<select id="colour-filter"><option value="all">All colours</option>${['Ochre','Clay','Natural','Olive'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>Material<select id="fabric-filter"><option value="all">All materials</option>${[...new Set(subset.map(p=>p.material))].map(m=>`<option>${m}</option>`).join('')}</select></label><label>Size<select id="size-filter"><option value="all">All sizes</option>${c.sizes.map(v=>`<option>${v}</option>`).join('')}</select></label><button class="text-link reset-filters">Reset filters</button><span class="result-count">${subset.length} design ideas</span></div><div id="product-grid" class="product-grid">${subset.map(productCard).join('')}</div><p class="fine-print">Illustrative collection. Confirm the final composition, dimensions, colour and availability with our team.</p></section>
<section class="section collection-details"><div class="container details-layout"><div data-aos><span class="tiny">THE DETAILS MAKE THE DIFFERENCE</span><h2>${['A cover, considered.','Comfort in every fold.','Set with intention.','Length. Texture. Character.','Layer with confidence.','A table that feels like you.'][index]}</h2><p>${['Look for the texture you love, the shape that fits and the finish that works for your space.','Think about drape, weight and where your throw will live. A lightweight layer and a generous blanket have different roles.','Start with the dimensions of your table, then choose the drop and the mood you would like to create.','Run a line of colour along your table or add a relaxed layer across a sideboard.','Choose an anchor colour, vary the scale of your textures, and give the eye somewhere calm to rest.','Choose a quiet base, introduce a soft accent and leave space for food, conversation and everyday rituals.'][index]}</p></div><dl class="detail-grid"><div>${icon('weave')}<dt>Materials to explore</dt><dd>${c.material}</dd></div><div>${icon('measure')}<dt>Measurements</dt><dd>${c.sizes.join(' · ')}</dd></div><div>${icon('sun')}<dt>Colour & light</dt><dd>View fabric in the light of your own room; screen colours may vary.</dd></div><div>${icon('wash')}<dt>Care instructions</dt><dd>Follow the final item’s care label. Ask for composition and washing details before ordering.</dd></div></dl></div></section>
<section class="section container size-section"><div class="size-illustration" data-aos>${sizingSvg(index)}<span>${index<4?'MEASURE FIRST. CHOOSE WITH CONFIDENCE.':'MAKE ROOM FOR EVERYDAY LIVING.'}</span></div><div data-aos><h2>${index<4?'The right fit.':'Space to feel at home.'}</h2><p>${index===0?'Measure the insert seam to seam, without compressing it. Check both width and height.':index===1?'Decide whether you want a draped accent or full coverage, then measure the furniture or area you want to cover.':index===2?'Measure the tabletop length and width. Add twice your preferred drop to both dimensions.':index===3?'Measure your table length and decide whether the runner should sit within the edge or extend beyond it.':'Measure the furniture and leave comfortable space around the pieces you use every day.'}</p><table class="size-table"><thead><tr><th>${index<4?'Explore dimensions':'Room setting'}</th><th>Before choosing</th></tr></thead><tbody>${c.sizes.map((s,j)=>`<tr><td>${s}</td><td>${['Check the space','Consider the proportions','Confirm the final fit','Ask for guidance'][j]}</td></tr>`).join('')}</tbody></table><p class="fine-print">Sizes shown are planning examples, not confirmed stock options.</p></div></section>
<section class="section container editorial-section">${sectionHead(['The beauty of a small detail.','Slow down, soften up.','Everyday is an occasion.','Let texture take the lead.','Your own kind of calm.','Gather, linger, repeat.'][index],'A closer look at the textures, proportions and combinations that make a space feel personal.')}<div class="editorial-grid"><div class="editorial-main" data-aos>${img(c.editorialImage||extras[index],c.name+' editorial inspiration')}<div><h3>${c.short}</h3><p>Start with the piece you love. Let the rest of the room follow.</p></div></div><div class="editorial-notes"><article><span class="note-icon">${icon('leaf')}</span><h3>Start with texture</h3><p>Mix an expressive weave with a quieter surface. Contrast creates interest without adding clutter.</p></article><article><span class="note-icon">${icon('heart')}</span><h3>Make it personal</h3><p>A familiar colour, a favourite chair, a table you gather around. Choose for the way you actually live.</p></article><article><span class="note-icon">${icon('thread')}</span><h3>Finish thoughtfully</h3><p>Keep the palette connected. A repeated tone ties different fabrics and objects together.</p></article></div></div></section>
<section class="section container swatch-section">${sectionHead('A palette to make your own.','Explore the character of each tone. Ask us about the colours available in your chosen item.')}<div class="swatch-list">${[['Warm ivory','A quiet, creamy foundation.','#e3d9c6'],['Golden ochre','A warm accent with depth.','#ba904d'],['Clay blush','An earthy, softened pink.','#b9816a'],['Olive grove','A grounded botanical note.','#74735b'],['Cocoa weave','A rich, warm neutral.','#695244'],['Natural flax','An easy, textured starting point.','#bcb19c']].map(([n,d,col])=>`<button class="swatch-row" data-tone="${n}"><span class="large-swatch" style="background:${col}"></span><span><strong>${n}</strong><small>${d}</small></span><span class="swatch-action">Enquire</span></button>`).join('')}</div></section>
<section class="section container collection-finish"><div><span class="tiny">A LITTLE GUIDANCE</span><h2>Before you choose.</h2><div class="accordions">${faq([['Can you help me coordinate items?','Tell us which pieces, colours and dimensions you are considering. We can discuss a coordinated direction before you make a decision.'],['What details should I check?','Ask for confirmed fibre composition, measurements, colour, care instructions, pricing and availability for your chosen item.'],['How do shipping and returns work?','Delivery destinations, costs, timing and return conditions are confirmed with your proposal before an order is accepted. See Shipping & Returns for the enquiry process.']])}</div></div><div class="finish-card"><span class="line-star">✳</span><h3>Let’s find<br>your perfect layer.</h3><p>Tell us about your room and the pieces you have in mind.</p>${button('Make an enquiry',`index.html?interest=${encodeURIComponent(c.name)}#contact`,'dark')}<a href="shipping-returns.html">Shipping & Returns</a></div></section>`;}
function sizingSvg(i){return `<svg viewBox="0 0 500 360" fill="none" stroke="currentColor" stroke-width="2" aria-label="${i===0?'Cushion measurement illustration':'Textile measurement illustration'}" role="img">${i===0?'<path d="M135 85Q250 55 365 85Q340 180 365 275Q250 300 135 275Q160 180 135 85Z"/><path stroke-dasharray="5 7" d="M150 100Q250 75 350 100Q328 180 350 260Q250 282 150 260Q171 180 150 100Z"/>':i===1?'<path d="m130 70 220 20-25 200-220-20Z"/><path d="m145 95 180 16-18 150-180-16Z" stroke-dasharray="5 5"/><path d="m105 270-5 15m20-14-5 15m20-14-5 15m20-14-5 15m20-14-5 15m20-14-5 15m20-14-5 15m20-14-5 15m20-14-5 15m20-14-5 15m20-14-5 15"/>':'<path d="m90 150 130-70 190 70-130 80Z"/><path d="M90 150v80l190 80 130-80v-80M280 230v80"/><path stroke-dasharray="6 6" d="m120 155 100-55 160 55-100 55Z"/>'}<path d="M100 45h300m-300-8v16m300-16v16M450 85v205m-8-205h16m-16 205h16"/><text x="250" y="30" text-anchor="middle" fill="currentColor" stroke="none" font-size="13">WIDTH</text><text x="470" y="190" fill="currentColor" stroke="none" font-size="13" transform="rotate(90 470 190)">LENGTH</text></svg>`;}
function carePage(){return `<section class="guide-hero container"><span class="tiny">KNOW YOUR TEXTILES</span><h1>Materials & Care</h1><p>Good information makes a beautiful choice easier.</p></section><section class="section container guide-grid">${Object.entries(materialData).map(([k,m])=>`<article>${img(m.image,k+' texture')}<h2>${k[0].toUpperCase()+k.slice(1)}</h2><p>${m.desc}</p><p><strong>Feel:</strong> ${m.feel}</p><p><strong>Care:</strong> ${m.care}</p></article>`).join('')}</section><section class="section container"><h2>Compare at a glance.</h2><div class="table-scroll"><table class="size-table"><thead><tr><th>Material</th><th>Character</th><th>Consider for</th><th>Care approach</th></tr></thead><tbody>${Object.entries(materialData).map(([k,m])=>`<tr><td>${k}</td><td>${m.feel}</td><td>${m.best}</td><td>${m.care}</td></tr>`).join('')}</tbody></table></div></section><section class="section container care-guide"><div><h2>Keep the lovely feeling.</h2><p>These are general care pointers. The individual care label always takes priority, especially for blends, dyes and decorative finishes.</p>${button('Ask about an item','index.html#contact','dark')}</div><div class="accordions">${faq([['Read the label first','Check fibre composition, wash temperature, drying method and ironing guidance before cleaning. A fabric family alone does not determine how the finished item should be cared for.'],['Wash thoughtfully','Separate colours, avoid overloading and use the cleaning method stated on the label. Test any treatment on a discreet area first.'],['Dry with care','Check whether tumble drying is permitted. Keep shape and avoid unnecessary heat; some pieces should be reshaped and dried flat.'],['Store well','Store clean, fully dry textiles in a dry, ventilated place. Fold gently and avoid prolonged direct sunlight.'],['Choose the correct dimensions','Measure the space and check the finished item dimensions, seam allowances where relevant, and any shrinkage information provided by the supplier.']])}</div></section>`;}
const policies={
'privacy-policy':{title:'Privacy Policy',intro:'How information shared through this website is handled.',sections:[['Information you provide','When you contact us, you provide your name, email address, enquiry topic and message. Please include only information relevant to your enquiry and avoid sensitive personal information.'],['How we use it','We use enquiry information to respond to your request, discuss products or collaboration opportunities, and keep a record of the conversation where necessary. We do not use an enquiry as permission to send marketing messages.'],['Processing and retention','Enquiries are sent to our designated corporate mailbox when email delivery is configured. Hosting and email providers may process information on our behalf. Records should be retained only as long as required for the enquiry and any applicable obligations.'],['Your choices','Contact the email address below to request access to, correction of or deletion of information you have shared. The business operating this site must confirm the applicable legal basis, retention period and any statutory exceptions before launch.'],['Website storage','This site stores a small browser preference to remember dismissal of the cookie notice. No advertising or analytics cookies are intentionally included in this version. See the Cookie Policy for details.'],['Contact and operator','The site is operated under the company name shown below. Company registration details, jurisdiction and privacy contact details must be confirmed by the operator before accepting live enquiries.']]},
 'terms-conditions':{title:'Terms & Conditions',intro:'Please read these terms before using the website or making an enquiry.',sections:[['About the collection','This website presents illustrative home textile collections and room styling ideas. Images may show generated or styled scenes. They do not guarantee that a specific item, finish or colour is available.'],['Product information','Final composition, measurements, care requirements, pricing and stock availability must be confirmed in writing before an order is accepted. Screen colour and image proportions may differ from the finished product.'],['Enquiries and orders','Submitting a form is an enquiry, not a completed purchase or a binding order. Any order requires separate confirmation of its scope, price, delivery arrangements and applicable terms. No payment is collected on this website.'],['Partnerships','Advertising and collaboration requests are considered individually. Scope, budget, deliverables, rights and timing must be agreed separately in writing.'],['Using this website','Use this website lawfully. Do not send malicious content, spam or material that infringes another person’s rights through the contact form.'],['Rights and applicable terms','Nothing in these draft terms is intended to restrict mandatory consumer rights. The operating business must supply its legal identity, applicable jurisdiction and final trading terms before commercial launch.']]},
 'cookies':{title:'Cookie Policy',intro:'A small preference. A clear explanation.',sections:[['Essential browser storage','We use localStorage under the key ht-cookie-notice to remember that you have dismissed the cookie notice. This value stays in your browser until you clear the site data. It is not an advertising identifier.'],['Contact form security','On PHP hosting, the contact form uses a short-lived session cookie to protect submissions against cross-site requests. This is used for form security and is not used for marketing.'],['Analytics and advertising','This version does not include intentional analytics, advertising pixels or social-media tracking scripts. If these are added later, this policy and any consent controls must be updated before they are enabled.'],['Managing your choices','You can remove stored site data using your browser settings. Clearing local storage causes the notice to reappear. Blocking essential session cookies may prevent the contact form from submitting.'],['Questions','Contact the corporate email shown below if you have questions about this website’s use of storage.']]},
 'shipping-returns':{title:'Shipping & Returns',intro:'Clear details, before you commit.',sections:[['Confirm before ordering','This website accepts enquiries rather than online checkout. Delivery destinations, charges and estimated timing are confirmed with the final proposal before any order is accepted.'],['Delivery information','Share your destination country and the items you are considering. Please do not send a full delivery address until our team needs it to prepare or fulfil an order.'],['Returns and exchanges','Ask for the applicable return window, eligibility, return costs and instructions before ordering. Personalised or made-to-order items may have different conditions where permitted by applicable law.'],['Damaged or incorrect items','Contact us with your order reference and a description of the issue. Keep the packaging and any relevant photographs so the matter can be assessed.'],['Your rights','The final terms must respect applicable consumer rights. The operating business must confirm its actual shipping and returns arrangements before commercial launch.']]}}
function policyPage(key){let p=policies[key];return `<section class="guide-hero container"><a class="back-link" href="index.html">Home / Information</a><h1>${p.title}</h1><p>${p.intro}</p></section><section class="section container legal-layout"><nav aria-label="Information pages">${Object.entries(policies).map(([s,v])=>`<a href="${s}.html" ${s===key?'aria-current="page"':''}>${v.title}</a>`).join('')}</nav><div class="legal-copy">${p.sections.map(([t,b])=>`<article><h2>${t}</h2><p>${b}</p></article>`).join('')}<article><h2>Get in touch.</h2><p>${esc(C.companyName)}</p><a href="mailto:${esc(C.email)}">${esc(C.email)}</a></article><p class="fine-print">Draft website information. Business-specific details must be completed before public commercial use.</p></div></section>`;}
