$$('[data-carousel]').forEach(el=>{const track=$('.carousel-track',el);let moving=false;function move(dir){if(moving)return;moving=true;let width=track.children[0].getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap||0);track.style.transition='none';if(dir<0){track.prepend(track.lastElementChild);track.style.transform=`translateX(-${width}px)`;}requestAnimationFrame(()=>requestAnimationFrame(()=>{track.style.transition='transform .65s cubic-bezier(.22,.61,.36,1)';track.style.transform=dir>0?`translateX(-${width}px)`:'translateX(0)';setTimeout(()=>{track.style.transition='none';if(dir>0)track.append(track.firstElementChild);track.style.transform='translateX(0)';moving=false;},660);}));} $('[data-prev]',el).onclick=()=>move(-1);$('[data-next]',el).onclick=()=>move(1);let startX=0,startY=0;track.style.touchAction='pan-y';track.addEventListener('touchstart',e=>{startX=e.touches[0].clientX;startY=e.touches[0].clientY;},{passive:true});track.addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-startX,dy=e.changedTouches[0].clientY-startY;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))move(dx<0?1:-1);},{passive:true});track.addEventListener('keydown',e=>{if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1);});let pointerX=0,pointerY=0,dragging=false;track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;pointerX=e.clientX;pointerY=e.clientY;dragging=true;});window.addEventListener('pointerup',e=>{if(!dragging)return;dragging=false;let dx=e.clientX-pointerX,dy=e.clientY-pointerY;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){el.dataset.dragged='true';move(dx<0?1:-1);setTimeout(()=>delete el.dataset.dragged,80);}});track.addEventListener('dragstart',e=>e.preventDefault());track.addEventListener('click',e=>{if(el.dataset.dragged){e.preventDefault();e.stopPropagation();}},true);track.tabIndex=0;track.setAttribute('aria-label','Product carousel. Use left and right arrow keys to browse.');});
$$('.texture-panel').forEach(p=>{const activate=()=>{let parent=p.parentElement;parent.style.setProperty('--panel-bg',`url('${p.dataset.bg}')`);parent.classList.add('unified');};p.onmouseenter=activate;p.onfocus=activate;p.parentElement.onmouseleave=()=>p.parentElement.classList.remove('unified');p.onblur=()=>p.parentElement.classList.remove('unified');});
