$$('[data-palette]').forEach(b=>b.onclick=()=>{$$('[data-palette]').forEach(t=>t.setAttribute('aria-selected',t===b));renderPalette(b.dataset.palette);});if($('#palette-content'))renderPalette('earth');
$$('[role=tablist]').forEach(list=>list.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let tabs=$$('[role=tab]',list),i=tabs.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();tabs[i].click();}));
$$('.hotspot').forEach(h=>h.onclick=e=>{if(e.target.closest('a'))return;let was=h.getAttribute('aria-expanded')==='true';$$('.hotspot').forEach(b=>b.setAttribute('aria-expanded','false'));h.setAttribute('aria-expanded',!was);});
const range=$('.comparison input');if(range)range.oninput=e=>$('.comparison').style.setProperty('--compare',e.target.value+'%');

document.addEventListener('click',e=>{let b=e.target.closest('[data-product]');if(b)showProduct(b.dataset.product);let tone=e.target.closest('[data-tone]');if(tone)location.href=`index.html?interest=${encodeURIComponent(tone.dataset.tone+' — '+document.title.split(' | ')[0])}#contact`;});
if($('#colour-filter')){['colour-filter','fabric-filter','size-filter'].forEach(id=>$('#'+id).onchange=filterProducts);$('.reset-filters').onclick=()=>{$$('.filter-bar select').forEach(s=>s.value='all');filterProducts();};}
$$('.contact-form').forEach(f=>{const interest=new URLSearchParams(location.search).get('interest');if(interest)$('textarea',f).value=`I would like to know more about ${interest}. `;f.onsubmit=async e=>{e.preventDefault();if(!f.reportValidity())return;const status=$('.form-status',f),submit=$('[type=submit]',f);status.textContent='Sending your request…';status.className='form-status';submit.disabled=true;let data=Object.fromEntries(new FormData(f));try{const tokenRes=await fetch(C.form.endpoint+'?action=token',{credentials:'same-origin',headers:{'Accept':'application/json'},signal:AbortSignal.timeout(15000)});if(!tokenRes.ok||!tokenRes.headers.get('content-type')?.includes('application/json'))throw Error('unavailable');const token=await tokenRes.json();if(!token.csrf)throw Error('unavailable');data.csrf=token.csrf;const res=await fetch(C.form.endpoint,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(20000)});let result=await res.json();if(!res.ok||result.success!==true)throw Error(result.message||'Your request could not be sent. Please try again later.');status.textContent=C.form.successMessage;status.classList.add('success');f.reset();}catch(err){status.textContent=err.message==='unavailable'?'Email delivery is not connected yet. Your request has not been sent. Please try again once the site’s contact service is available.':err.message;status.classList.add('error');}finally{submit.disabled=false;}};});
