function enhancedWire(){
$('.header-search').onsubmit=e=>{e.preventDefault();const value=$('.header-search input').value;$('#search-dialog').showModal();$('#site-search').value=value;search(value);$('#site-search').focus();};
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const cycle=(el,selector,delay)=>{const items=$$(selector,el);items.forEach((item,n)=>item.setAttribute('aria-hidden',n!==0));let i=0;if(items.length<2||reduced)return;let visible=false;new IntersectionObserver(entries=>visible=entries[0].isIntersecting).observe(el);setInterval(()=>{if(!visible||document.hidden||el.matches(':hover,:focus-within'))return;items[i].classList.remove('active');items[i].setAttribute('aria-hidden','true');i=(i+1)%items.length;items[i].classList.add('active');items[i].setAttribute('aria-hidden','false');},delay);};
$$('[data-autoslide]').forEach((el,i)=>cycle(el,':scope>img',4600+i*600));$$('[data-textslide]').forEach(el=>cycle(el,':scope>div',6500));
$$('.gallery-select button').forEach(b=>b.onclick=()=>{let section=b.closest('.atelier-gallery');$$('.gallery-select button',section).forEach(x=>x.classList.toggle('active',x===b));$$('.gallery-mosaic figure',section).forEach(f=>{f.classList.toggle('muted',b.dataset.galleryFilter!=='all'&&f.dataset.kind!==b.dataset.galleryFilter);});});
$$('[data-workshop]').forEach(b=>b.onclick=()=>{let section=b.closest('.workshop');$$('[data-workshop]',section).forEach(x=>x.setAttribute('aria-selected',x===b));$$('.workshop-photo',section).forEach((im,i)=>im.classList.toggle('active',i===Number(b.dataset.workshop)));});
$$('details').forEach(d=>{const summary=$('summary',d);let animation;summary.onclick=e=>{e.preventDefault();if(animation)animation.cancel();let start=d.offsetHeight;if(!d.open){d.open=true;let end=d.offsetHeight;animation=d.animate({height:[start+'px',end+'px']},{duration:360,easing:'cubic-bezier(.25,.7,.2,1)'});d.style.overflow='hidden';animation.onfinish=()=>{d.style.overflow='';animation=null;};}else{animation=d.animate({height:[start+'px',summary.offsetHeight+36+'px']},{duration:300,easing:'ease-in-out'});d.style.overflow='hidden';animation.onfinish=()=>{d.open=false;d.style.overflow='';animation=null;};}};});
}

