function finishWire(){
const form=$('.header-search'),input=$('input',form),box=$('.search-suggestions',form);let selected=-1;
const entries=[...C.collections.map(c=>({title:c.name,detail:c.material,url:link(c.slug),image:c.image})),{title:'Materials & Care',detail:'Your fabric guide',url:'materials-care.html',image:'fabric.avif'},{title:'Room inspiration',detail:'Ideas for your space',url:'index.html#room-inspiration',image:C.appearance.lookPhoto},...products.map(p=>({title:p.name,detail:p.material+' · '+p.size,url:link(p.collection),image:p.image}))];
const close=()=>{box.hidden=true;input.setAttribute('aria-expanded','false');selected=-1;};
const suggest=()=>{let q=input.value.trim().toLowerCase();const found=entries.filter(x=>(x.title+' '+x.detail).toLowerCase().includes(q)).slice(0,5);selected=-1;box.innerHTML=`<div class="suggestion-heading"><span>${q?'Matching textures':'A little inspiration'}</span><small>${q?found.length+' ideas':'Explore the collection'}</small></div>${found.length?found.map(e=>`<a class="suggestion" href="${e.url}">${img(e.image,e.title)}<span><strong>${esc(e.title)}</strong><small>${esc(e.detail)}</small></span><b>↗</b></a>`).join(''):'<p class="search-empty">No matches yet. Try linen, cushions or care.</p>'}<button type="button" class="search-all">See all results ${icon('arrow')}</button>`;box.hidden=false;input.setAttribute('aria-expanded','true');$('.search-all',box).onclick=()=>{close();$('#search-dialog').showModal();$('#site-search').value=input.value;search(input.value);$('#site-search').focus();};};
input.addEventListener('focus',suggest);input.addEventListener('input',suggest);
input.addEventListener('keydown',e=>{if(e.key==='Escape'){close();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(box.hidden)suggest();const links=$$('a',box);if(!links.length)return;selected=(selected+(e.key==='ArrowDown'?1:-1)+links.length)%links.length;links.forEach((a,i)=>a.classList.toggle('selected',i===selected));}else if(e.key==='Enter'&&selected>=0){e.preventDefault();$$('a',box)[selected].click();}});
form.addEventListener('focusout',()=>setTimeout(()=>{if(!form.contains(document.activeElement))close();},0));document.addEventListener('click',e=>{if(!form.contains(e.target))close();});form.addEventListener('submit',close);
$$('.cube-scene').forEach(scene=>{
const cube=$('.photo-cube',scene);
new ResizeObserver(entries=>scene.style.setProperty('--cube-depth',entries[0].contentRect.width/2+'px')).observe(scene);
if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
let turn=0,visible=false,started=false;
const rotate=()=>{cube.style.transform=`translateZ(calc(-1 * var(--cube-depth))) rotateY(${--turn*90}deg)`;};
const start=()=>{if(started||!visible||document.hidden)return;started=true;requestAnimationFrame(()=>requestAnimationFrame(rotate));setInterval(()=>{if(visible&&!document.hidden&&!scene.matches(':hover'))rotate();},C.appearance.cubeInterval);};
new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;start();}).observe(scene);
document.addEventListener('visibilitychange',start);
window.addEventListener('pageshow',event=>{if(event.persisted&&visible&&!document.hidden)rotate();});
});
}
function applyConfiguredContent(){
Object.entries(C.theme||{}).forEach(([k,v])=>document.documentElement.style.setProperty('--'+k,v));
const apply=(root,fields)=>{if(!root||!fields)return;for(const item of fields.text||[]){const el=item.selector?root.querySelector(':scope > '+item.selector):root;if(el&&el.childNodes[item.node]?.nodeType===3)el.childNodes[item.node].textContent=item.value;}for(const item of fields.images||[]){const el=root.querySelector(':scope > '+item.selector);if(el){el.src=item.src;el.alt=item.alt;}}for(const item of fields.links||[]){const el=root.querySelector(':scope > '+item.selector);if(el)el.setAttribute('href',item.href);}};
apply($('#header'),C.sharedContent?.header);apply($('#footer'),C.sharedContent?.footer);
const page=C.pages?.[currentPage];if(page){if(page.title)document.title=page.title+' | '+C.titleSuffix;const sections=$$('main>section');for(const s of page.sections||[]){const target=sections[s.position];if(s.enabled===false){target?.remove();continue;}Object.entries(s.styles||{}).forEach(([k,v])=>target?.style.setProperty(k,v));apply(target,s);}}
}

async function init(){try{C=window.SITE_CONFIG;if(!C)throw Error('Configuration unavailable');Object.assign(materialData,C.materials);Object.assign(palettes,C.palettes);Object.assign(policies,C.policies);currentPage=location.pathname.split('/').pop().replace('.html','')||'index';buildProducts();layout();let c=C.collections.find(c=>c.slug===currentPage),title='Home';if(c){$('#main').innerHTML=collection(c,C.collections.indexOf(c));title=c.name;}else if(currentPage==='materials-care'){$('#main').innerHTML=carePage();title='Materials & Care';}else if(policies[currentPage]){$('#main').innerHTML=policyPage(currentPage);title=policies[currentPage].title;}else $('#main').innerHTML=home();document.title=title+' | '+C.titleSuffix;$('link[rel=icon]').href=C.favicon;enhancePage(c);finishPage(c);applyConfiguredContent();wire();enhancedWire();finishWire();document.body.classList.add('ready');}catch(err){$('#main').innerHTML='<div class="container section"><h1>We’ll be right back.</h1><p>The collection could not load. Please refresh the page.</p></div>';console.error(err);}}
window.addEventListener('pageshow',()=>document.body.classList.remove('leaving'));init();
